        "desc": "感谢“华夏基金·红色火箭”对本期节目的支持。本期节目我们读《也许你该找个人聊聊》，作者 洛莉· 戈特利布 。 \n\n《也许你该找个人聊聊》出版于2019年，是一位心理治疗师的回忆录，讲述了发生在诊室中的故事， 记录了4位来访者的治疗过程，同时 诚实地写下她自己崩溃后接受治疗的经过。5条治疗线相互交织，回答同一个问题：人如何面对痛苦，又如何改变。 从治疗师和来访者的双重视角展现了心理治疗的过程， 让我们发现：身份背景虽相异，但人类面对的烦恼却相通，爱与被爱、遗憾、选择、控制、不确定、死亡，这些都是身而为人必须共同学习与面对的议题，而 治疗的本质“找个人聊聊”，通过打开心门，言说痛苦，从而获得觉察、勇气、成长与改变，是“ 一个关于心理治疗的故事，也是关于生而为人的故事。” \n\n洛莉· 戈特利布（1966-）， 美国作家，资深心理治疗师。曾从事 电视剧集开发与编剧工作。后进入 斯坦福医学院学习， 因渴望深度倾听病人的痛苦而非流水线问诊， 转向心理咨询与写作，取得 临床心理学硕士学位及 婚姻与家庭治疗师（MFT）执照 ，在洛杉矶开业。她为 《大西洋月刊》撰写专栏“亲爱的治疗师”， 她的 TED演讲是2019年播放率最高的十大演讲之一， 播客“亲爱的治疗师”主播，也 经常作为心理健康话题的专家，出现在知名电视和广播节目中。 \n\n你会听到： \n1、 00:07:42 介绍作品主要内容。 \n2、作者洛莉简介，她的心理咨询背景和流派。什么是“戈特曼方法”？“四骑士”指的是什么？ \n3、分享阅读感受。和之前读过的心理学类社科作品有什么不同？ \n4、书中记录的5位来访者中，对谁印象深刻？分享精彩片段。 \n5、 如何才能最大程度地利用咨询时间？建立最佳、最有效或最令人满意的治疗关系的关键是什么？ \n片头曲：上天桥 \n片尾曲：白西 \n主播：大壹 / 超哥 / 星光 \n“红色火箭”是由华夏基金出品的一款 专门针对指数投资的数据分析和决策辅助工具。直接在微信小程序里搜索“红色火箭”，就可以免费使用。",
