        "title": "vol.1423 生活就是痛苦的线串着那不多的名为快乐的珍珠",
        "desc": "曹工终于带着新专辑《木楼人》回来了，但这回咱们不聊音乐，改聊他身边的“奇葩”朋友们。有酒后在酒店房间凭空变出一棵假棕榈树的美国人，有从电子乐玩到红酒又回归民谣的音乐人，还有隐居意大利山里天天骗人爬山。曹工感慨人到中年，生活的本质，是一根痛苦的长线，串起一颗颗为数不多的快乐珍珠。而那些奇怪却又真实的人，或许才是抵抗乏味生活的唯一解药！\n\n主播 / 相征&nbsp;\n\n嘉宾 / 曹璞\n\n音频后期 / 陆凯BBBBUDDHA\n\n音频上传 / 恬恬\n\nTimeline: \n\n00:04:32 《木楼人》这次真的发了\n\n00:10:22 中年人只能聊痛苦。。。吗？\n\n00:14:19 喝多了搬绿植为了净化空气\n\n00:24:18 摇滚乐可真行！\n\n00:33:37 喜欢听点碾核！\n\n00:40:28 家庭旅行充满挑战\n\n00:51:59 周围都是怪人，但我正常呀\n\n00:53:16 木楼人 - 陌生的你\n\n00:58:29 去趟海边交个女朋友\n\n01:05:49 “板上钉钉”的故事&nbsp;\n\n01:12:07 建筑夫妇爱爬山\n\n01:30:57 聊聊有趣的音乐人\n\n01:45:01 饿了吃观赏蟹？\n\n01:50:54 网络时代下的真实社交需求&nbsp;\n\n01:53:18 木楼人 - 子夜之前\n\n今年十一长假，由划水怪&amp;miya带队，七天六晚带你深入越后妻有和轻井泽。这片藏在日本新潟县的雪国山谷，是全世界独一无二的大地艺术祭现场。这次，不仅是一场艺术盛宴，更是一场舌尖之旅——从品尝当地新米到品鉴小诸威士忌，从妻有猪到和牛铁板烧，从药汤温泉到轻井泽骑行，吃喝玩乐一举拿下！名额有限，详情可进入微信小程序“大内夜市”查看。\n\n恰逢周年，大内十三周年限定主题周边正式上线。在香港的俚语里，“My Cup Of Tea”代表合心我意、投缘，于是我们将Tea替换成T恤的缩写Tee，于是就有了“MY CUP OF TEE 係我杯茶”的周年主题。而本次周边分为是定制马克杯、主题T恤两款单品，也推出了成套纪念礼盒（礼盒附赠随机主播签名嗷）～\n\n还记得那些一起笑过、燃过、感动过的时刻吗？我们没忘，也不想忘。于是，我们把来自“浪谈”宇宙的NBA节目、漫画节目和东瀛野望录里的动人句子，写进这件由杨凯老师亲自设计的T恤中，致敬彼此相伴的100小时时光。微信搜索小程序“大内夜市”，即可购买～\n\n深夜谈谈招聘啦，本次开放岗位\n\n全职：1、视频编导（北京/上海）&nbsp;2、商务BD&amp;AE （上海）\n\n感兴趣的朋友们请发送求职信+简历+个人作品请发送至邮箱jobs@midnightalks.com\n\n-你还可以在这里找到我们：\n\n小红书：@深夜谈谈、@相征terry、 @miya\n\nB站：@大内密谈midnightalks\n\n视频号&amp;抖音：@深夜谈谈\n\n微博：@大内密谈\n\n微信公众号：大内密谈\n\n商务合作邮箱：biz@midnightalks.com\n\n加听众群：加深夜谈谈子微信（微信号:SYTT-midnightalks2）并回复【听众群】即可进群。",
