        "full": "【开场】\n本期《基本无害》带来「可能是关于越野跑补给和营养最好的分享 ft.海怪」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《基本无害》播出「可能是关于越野跑补给和营养最好的分享 ft.海怪」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 海怪-怪怪\n▸ 午夜骑手毛冬\n▸ 三个月前，刚刚韧带撕裂（还不知情）的阿毛跟越野跑大神海怪和资深私补wei一起聊了聊越野跑的补给和营养。\n▸ 三个月后的今天小毛已经健步如飞（可能），踏上了跑向UTMB occ组别的旅程，祝阿毛一切顺利，祝大家都能健康无伤的享受户外。\n▸ 暗号有效期：8月24日——10月31日\n▸ 在玉龙山脚下录播客\n▸ 介绍一下海怪\n▸ 海怪越野跑的 key facts\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“地平线8号月壤色”\n\n【深度解读】\n本期主题：「可能是关于越野跑补给和营养最好的分享 ft.海怪」。本期主题：「可能是关于越野跑补给和营养最好的分享 ft.海怪」。本期《基本无害》围绕「可能是关于越野跑补给和营养最好的分享 ft.海怪」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：@海怪-怪怪。@午夜骑手毛冬。\n\n【为什么值得听】\n延续《基本无害》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《基本无害》一贯的内容水准，值得点开收听完整内容。",
