        "full": "【开场】\n本期《贤者时间》带来「新故事到来前，会先伪装成微小的失败」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《贤者时间》播出「新故事到来前，会先伪装成微小的失败」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 苍山洱海边，我们聊了聊如何制造变化、应对变化，以及两个笨蛋硬闯挪威的一些笨笨故事。\n▸ 去做那个多少能让自己兴奋的决定\n▸ 都快忘了世上除了工位还有沙漠\n▸ 一个坏良心的建议\n▸ 新的骨骼会从旧伤的钙化里生长出来\n▸ 唉！都是为了狗好\n▸ 浅谈欧洲和江苏的区别/她不是坏人却又没有好到底/一位留子和他滔滔不绝的创伤/大厂没教会我的事/高端养老院有独特的掌掴方式\n▸ ✈️大理新家 roomtour 🌳\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【深度解读】\n本期主题：「新故事到来前，会先伪装成微小的失败」。本期主题：「新故事到来前，会先伪装成微小的失败」。本期《贤者时间》围绕「新故事到来前，会先伪装成微小的失败」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：苍山洱海边，我们聊了聊如何制造变化、应对变化，以及两个笨蛋硬闯挪威的一些笨笨故事。22:44 去做那个多少能让自己兴奋的决定。\n\n【为什么值得听】\n延续《贤者时间》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《贤者时间》一贯的内容水准，值得点开收听完整内容。",
