        "full": "【开场】\n本期《大内密探》带来「生活就是痛苦的线串着那不多的名为快乐的珍珠」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《大内密探》播出「生活就是痛苦的线串着那不多的名为快乐的珍珠」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 曹工终于带着新专辑《木楼人》回来了，但这回咱们不聊音乐，改聊他身边的“奇葩”朋友们。有酒后在酒店房间凭空变出一棵假棕榈树的美国人，有从电子乐玩到红酒又回归民谣的音乐人，还有隐居意大利山里天天骗人爬山。曹工感慨人到中年，生活的本质，是一根痛苦\n▸ 主播 / 相征\n▸ 嘉宾 / 曹璞\n▸ 音频后期 / 陆凯BBBBUDDHA\n▸ 音频上传 / 恬恬\n▸ 《木楼人》这次真的发了\n▸ 中年人只能聊痛苦。。。吗？\n▸ 喝多了搬绿植为了净化空气\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“My Cup Of Tea”\n“MY CUP OF TEE 係我杯茶”\n\n【深度解读】\n本期主题：「生活就是痛苦的线串着那不多的名为快乐的珍珠」。本期主题：「生活就是痛苦的线串着那不多的名为快乐的珍珠」。本期《大内密探》围绕「生活就是痛苦的线串着那不多的名为快乐的珍珠」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：曹工终于带着新专辑《木楼人》回来了，但这回咱们不聊音乐，改聊他身边的“奇葩”朋友们。有酒后在酒店房间凭空变出一棵假棕榈树的美国人，有从电子乐玩到红酒又回归民谣的音乐人，还有隐居意大利山里天天骗人爬山。\n\n【为什么值得听】\n延续《大内密探》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《大内密探》一贯的内容水准，值得点开收听完整内容。",
