        "summary": "秦孝公任用商鞅两次变法，废井田、奖军功、推行县制与连坐法，秦由此崛起为战国最强国，为统一六国奠基。",
        "background": "战国中期，七雄并立、兼并战争白热化。秦国偏居西陲，被中原诸侯视为「戎狄」。秦孝公即位后痛感落后，发布求贤令：「宾客群臣有能出奇计强秦者，吾且尊官，与之分土。」商鞅由魏入秦，以「霸道」之说打动孝公，获任左庶长主持变法。",
        "event": "第一次变法（公元前 356 年）：编定户籍、实行什伍连坐、奖励军功（按斩首赐爵）、奖励耕织、重农抑商、废除贵族世袭。第二次变法（公元前 350 年）：废井田开阡陌承认土地私有、推行县制、迁都咸阳、统一度量衡、制定秦律。",
        "impact": "短期内秦「道不拾遗，山无盗贼，家给人足」，军功爵制让底层获得上升通道，秦军成为「虎狼之师」。但严刑峻法与高压动员也埋下秦二世而亡的伏笔。这场变法是「制度创新驱动国家崛起」的最早成体系案例。",
