        "background": "东汉末年群雄逐鹿，曹操在官渡之战击败袁绍后基本统一北方，公元 208 年挥师南下，荆州刘表之子刘琮举州投降，刘备退守夏口。曹操得荆州水军、兵临赤壁，致书孙权「会猎于吴」，意在迫使东吴投降。此时东吴主降派占多数，鲁肃引刘备代表诸葛亮赴柴桑说服孙权。",
        "event": "周瑜任联军统帅，以火攻为主：诈降将黄盖率「斗舰」十艘装满干柴硫磺，趁着东南风冲向曹军船阵，火势延及岸上营寨。曹军不习水土、疫病流行，被火攻与连锁焚烧击溃，曹操北撤，留曹仁守江陵。",
