        "summary": "唐贞观三年，玄奘私自出长安，历经 17 年西行 5 万余里抵达天竺取经，回国后主持译经 19 年，共译佛典 75 部 1335 卷。",
        "background": "隋唐之际佛教传入中国已数百年，但经文翻译错漏甚多，「南橘北枳」般失真。玄奘（俗名陈祎）13 岁出家，研读各家经典后产生疑问：「佛陀本意究竟如何？」遂立志「至天竺问佛」。唐初因战乱禁止百姓出关，他上表请行未获批准。贞观三年（627 年）长安饥荒，他混在逃荒人群中出城，独自西行。",
        "event": "经高昌国受国王鞠文泰礼遇并资助，穿越葱岭（帕米尔高原）、铁门关、迦毕试国、阿姆河北，抵达中亚重镇撒马尔罕。再南行至迦湿弥罗（今克什米尔）学习两年、那烂陀寺跟戒贤法师学《瑜伽师地论》5 年。贞观十九年（645 年）正月回到长安，携带佛经 657 部、佛像 7 尊。",
        "impact": "玄奘归国主持译场，培养出窥基、圆测等一代宗匠。口述《大唐西域记》12 卷，是研究中亚、南亚 7 世纪历史的最高等级一手文献。玄奘精神在民间演化为「西游记」，成为中国「求知者」的原型意象。一位僧人凭一人之力，把东方文明与整个南亚、中亚文明重新焊接在一起。",
        "prompt": "写一段「为一件相信的事走了很久」的经历。① 启程时你带走了什么、又留下了什么？② 在路上哪一刻你想过放弃？③ 抵达那天和出发那天相比，你最不一样的地方是哪里？"
