        "background": "1804 年拿破仑称帝后以一己之力挑战整个欧洲秩序，先后击败五次反法同盟，但 1812 年征俄失败、1813 年莱比锡战败、1814 年 4 月巴黎陷落被迫退位流放厄尔巴岛。战胜国（俄、英、奥、普）需要决定：法国被削弱到什么程度？旧王朝全部复辟？新秩序如何避免再次出现拿破仑？",
        "event": "1814 年 9 月—1815 年 6 月，奥地利首相梅特涅主持会议，几乎所有欧洲国家派代表参加。会议拒绝「惩罚性」肢解法国，反而保留其领土；恢复波旁王朝复辟；建立「神圣同盟」和「四国同盟」（俄英奥普）；形成「均势」原则——任何一国扩张都将被其他列强共同制衡；1815 年 3 月拿破仑百日王朝再度崛起又迅速被击溃，进一步巩固了会议成果。",
        "impact": "维也纳体系维持了欧洲主要大国之间近百年（直到 1914 年一战爆发）的相对和平——这是欧洲近代史上最长的「无大战」时期。它确立了「通过会议解决争端」的多边外交范式，至今仍存在于联合国、G20 等机制中。但它也压制了民族独立诉求（德意志、意大利的整合），让民族主义在地下生长，最终在 1848 年革命和 1871 年统一中爆发。",
