      "show": "忽左忽右",
      "title": "495 陆大鹏谈莎士比亚戏剧与英国历史的互相影响",
      "desc": "- 导语 -\n莎士比亚，一个世界文学绕不开的名字。其魅力不仅在于传世的经典文本，更植根于他所处的时代语境与剧场生态。为什么莎剧会充满市井趣味的反差感？在一个尚无今天这套原创观念的时代，如何理解莎士比亚的原创性？他为现代英语贡献了哪些至今仍在使用的日常表达？覆盖中世纪英格兰历史的大转折，莎翁的历史剧如何改编史实，又如何回应都铎王朝的政治需要？请听本期嘉宾陆大鹏带来的精彩分享！\n本期节目与「戏不戏 · 英国舞台季」联合呈现。\n- 本期话题成员 -\n程衍樑（微博@GrenadierGuard2）\n陆大鹏，世界史学者，英德译者。著有《德意志贵族》《巴比伦怪物：魏玛共和国犯罪鉴证实录》等，译有《阿拉伯的劳伦斯》等。《怪东西Weird History》播客主播。\n- 时间轴 -\n06:27 论莎剧之妙处：好故事、语言美与多层用典\n11:10 从《亨利五世》的反差看英国文学的异质性\n16:09 16世纪剧场里的黄段子与小吃摊\n18:06 莎士比亚的原创性不在于故事梗概，而是对原材料的加工\n21:31 塑造现代英语的两大文本：詹姆斯一世钦定版《圣经》与莎士比亚戏剧\n29:23 莎士比亚历史剧的取材：从金雀花王朝到都铎王朝崛起\n41:17 《亨利八世》为何回避安妮·博林被处死\n45:52 虔诚、武德、壮志：《亨利五世》中的好君主标准\n50:24 二战背景下对莎剧的爱国主义改编\n57:13 「整个世界就是一个舞台」：环球剧院的传统与重建\n01:06:02 费雯丽、「甘道夫」与焦晃：莎剧表演出身的实力派演员们\n01:10:41 从黑泽明到《狮子王》：莎士比亚作品的跨文化转译\n- 支持我们的赞助商是对我们最好的支持 -\n本期节目由英国驻华使领馆与英国旅游局特别策划，英国舞台季邀请您一起探索英国表演艺术的台前幕后，也重新想象艺术如何连接今天的我们。\n如果你喜欢本期节目，也可以前往 「 戏不戏 · 英国舞台季 」 收听本系列企划的其他节目。\n更多精彩活动和内容，欢迎关注英国驻华使领馆及英国旅游局社交媒体：\n英国驻华使馆 \n英国驻上海总领馆 \n英国驻广州总领事馆 \n英国驻重庆总领事馆 \n英国驻武汉总领事馆 \n英国旅游局 \n- 制作团队 -\n声音设计 hotair\n节目统筹 禾放\n节目运营 小米粒\n节目制作 思钊 Yo\nlogo设计 杨文骥\n- 音乐 -\nDanse Macabre - Busy Strings - Kevin MacLeod\n- 本节目由JustPod出品 © 2026 上海斛律网络科技有限公司 -\n- 互动方式 -\n商务合作：ad@justpod.fm\n微博：@忽左忽右leftright @播客一下 @JustPod\n微信公众号：忽左忽右Leftright / JustPod / 播客一下\n小红书：JustPod气氛组 / 忽左忽右\nB站：忽左忽右leftright\n抖音：忽左忽右",
      "pub": "Tue, 25 Aug 2026 09:00:00 GMT",
      "link": "https://www.xiaoyuzhoufm.com/episode/6a8d2078ef65145dfcc4f6d5?utm_source=rss",
      "core": "本期《忽左忽右》围绕「陆大鹏谈莎士比亚戏剧与英国历史的互相影响」展开。人文深度对谈，话题广而有深度，知识密度高，延续节目一贯的深度与质感。",
