        "它的深度来自「愿意花一整期把一个问题讲透」——不追热点标题，而是把背景、现场与反思一层层铺开，越听越有后劲。当期重点：莎士比亚，一个世界文学绕不开的名字。其魅力不仅在于传世的经典文本，更植根于他所处的时代语境与剧场生态。"
