      "desc": "这是一期关于美国财政部长贝森特最近所作所为所想的学习笔记。\n大家好，我是大卫翁，\"起朱楼宴宾客\"是我用来记录这个大时代的播客节目。\n9月4日昆明线下活动报名链接：\nhttps://mp.weixin.qq.com/s/WEP4Bd7B-BTe5DG6WyIHCg \n或者扫描下方小程序码：\n简明时间轴及参考资料链接：\n02:33 贝森特最近干的几件大事：和日本联合干预汇市、喊话美联储扩大FIMA、加码美债回购规模\n05:52 贝森特的个人经历对他政策思路的影响\n参考资料：\n美联社的采访 \nSemafor去年底的深度文章 《How Scott Bessent took over the global economy》 \n他在纽约经济俱乐部“美国250周年”晚宴上的演讲稿：21世纪的美国经济外交艺术 \n世界黄金协会： Markets may not buy the buybacks \n24:40 和日本联手救日元，贝森特图什么？\n参考资料：\n中田敦彦的Youtube大学： 【日米為替介入】なぜアメリカは動いたのか？米国債防衛のカラクリと思惑 \nFortune 《Scott Bessent is using moves from his hedge fund days to prop up Japan’s yen—and America’s $40 trillion national debt》 \n41:36 贝森特加码美债回购，失败了吗？\n参考资料：\n纽约梅隆银行BNY ： U.S. Treasury Buybacks, Signal Matters More than Size \nWall Street Journal： Why Scott Bessent Is Playing With the Treasury Market \n公众号Spread Trading： 《原来贝森特才是债市义警》 \nIMF: 《Testing the Liquidity Support Effects of the U.S. Treasury Buyback Program》 \n52:52 总结：贝森特过去靠判断政府什么时候会向市场认输来“赚钱”，现在他的工作是让市场相信政府根本不会认输\n欢迎关注我的新书《资产配置行动指南》，解读和购买链接在这里： 158. 播客里聊了四年的资产配置，我把它做成了一本《行动指南》 \n欢迎订阅我的Substack频道，它是一个以英文为主的频道： hubris2025.substack.com \n欢迎关注我和雨白、小跑新制作的时事聊天节目 《不熄灯Lights On》 \n欢迎关注我的生活方式类节目《犬生活》， 《纽约有一种气质叫“都行”｜和杨蒙恩的临别闲聊局》 最新上线！\n欢迎加入我的 知识星球 ，我正在好好运营那一片后花园。\n欢迎在评论区互动，或者给我写邮件，邮箱地址qizhulouyanbinke@gmail.com。\n节目BGM：\nJodymoon - the long way around\nIn the pool\n节目后期：大卫翁",
