      "show": "半拿铁",
      "title": "No.215 华为不造车，鸿蒙智行到底是什么？",
      "desc": "主播 | 潇磊 刘飞\n本期节目感谢鸿蒙智行提供信息支持\n————\n今天的节目，我们来讲鸿蒙智行。华为反复强调不造车，却深度参与产品定义、智能技术、品牌营销和零售渠道；合作车企则承担整车工程、供应链、生产制造与质量管理。这套跟其它品牌都不一样的分工，究竟是怎么跑起来的？\n本期节目，我们会从2012年前后华为对车联网的早期探索讲起，复盘车BU成立、手机业务受挫、余承东寻找合作伙伴，以及赛力斯SF5试水和问界诞生。我们也会拆开问界模式的三方分工，看看华为怎样把十年消费电子经验搬进汽车行业，又怎么靠新M7与M9完成一次“起死回生”。\n问界跑通之后，智界、享界、尊界和尚界相继加入。五家车企禀赋不同、价格带从十几万元延伸到百万元以上，鸿蒙智行也从商场里的华为门店，逐渐长出独立的体验中心和销交服一体化用户中心。与此同时，华为又把汽车技术装进引望，继续做面向全行业的“卖水人”。\n当汽车越来越像一台大型智能终端，规模、数据、技术与法规将怎样共同决定下一阶段的竞争？坐吧，来杯半拿铁，我们边喝边唠。\n————\n潇磊、刘飞的声音已授权给豆包、剪映等字节系产品使用若干年。\n在视频平台看到的无真人出镜、用我们的音色生成的 AI 内容，均非我们制作。\n————\n半拿铁宇宙之： 半拿铁·周刊 传送门，欢迎酌情收听\n半拿铁宇宙之： 半拿铁·故事篇 传送门，欢迎酌情收听及购买\n�听友投稿邮箱：bannatie@163.com\n️杭州特调「芝麻·半拿铁」的品尝地：西湖区华星路 【01coffee】\n️上海特调「米乳·半拿铁」的品尝地：前滩公园巷 【彼屯 between 自然商店】\n�半拿铁周边购买淘宝店：小羊商店Sheepedia&nbsp;\n� 半拿铁周边之：《人工智能风云录》纸质书，可在各大电商平台购买\n————\n时间轴： \n01:34 &nbsp;&nbsp;&nbsp;&nbsp;鸿蒙智行概况及起源\n12:45 &nbsp;&nbsp;&nbsp;&nbsp;智选车模式与问界品牌发展\n27:53 &nbsp;&nbsp;&nbsp;&nbsp;M9 爆款与余式打法\n47:21 &nbsp;&nbsp;&nbsp;&nbsp;五界布局与车企合作\n01:14:06 &nbsp;&nbsp;鸿蒙智行渠道扩张与不造车战略\n01:27:18 &nbsp;&nbsp;汽车智能化体验的未来与行业生态分析\n01:40:03 &nbsp;&nbsp;读评论\n————\n\n余承东 &amp; 贾健旭聊尚界诞生故事： \nhttps://weixin.qq.com/sph/ASo2Z4aU32 \n余承东对鸿蒙智行的总结： \n主要参考资料： \n\n《华为不造车往事》 窦亚娟 晚点Auto\n\n《华为怎样复制问界》 安丽敏 财新周刊\n\n《华为汽车放手一搏》 安丽敏 张而弛 财新周刊\n\n《何为华为不造车？》 安丽敏 张而弛 财新周刊\n\n《华为车BU分拆即将完成 新超级供应商崛起？》 安丽敏 财新\n\n《华为将为问界生态品牌建设销售渠道》 安丽敏 财新\n\n《问界M7订单破5万，余承东称\"起死回生\"，发生了什么？》 肖逸思 第一财经\n\n《余承东：华为手机崛起奇迹的操盘手》 环球企业家\n\n《华为猛将余承东：一路杀城，来到造车前线》 澎湃新闻\n\n《\"猛将\"余承东》 路世明 锌财经\n\n《新车太多装不下了？华为卖车渠道正\"一统四界\"，计划建独立鸿蒙智行门店》 孙磊 每日经济新闻\n\n《卖车渠道有变？华为计划建设独立鸿蒙智行门店》 宋豆豆 21世纪经济报道\n\n《尚界成为车圈现象级新秀背后：上汽联手华为，如何实现1+1&gt;2》 吴遇利 澎湃新闻\n\n《贾健旭余承东揭秘尚界诞生：华为拒绝又被说服，双方磨合两月》 易车\n\n《打造豪华轿车市场新标杆，享界S9助北汽蓝谷打开市场空间》 第一财经\n\n《江淮汽车敢为人先 打造\"时代旗舰\"尊界S800顶级豪华轿车新范式》 新华网\n\n《尊界S800车型批量投产之后预计8月中旬交付》 icebin 动点科技\n\n《四界老板同台直播》 央视新闻\n\n《\"四界\"老总\"合体直播\"！余承东透露鸿蒙智行多个信息，称\"很多车厂想合作但手里没有资源了\"》 孙磊 每日经济新闻\n\n《中国经济引力场》 中央广播电视总台央视新闻\n\n《华为与上汽合作首款车型下周开启预订 上汽集团涨停》 证券时报\n\n《智界事业部升级为独立事业部》 21世纪经济报道\n\n《尹同跃：有分歧的时候听华为的，意见一致的时候听奇瑞的》 观察者网\n\n《贾健旭再抛金句：20万以下\"华为车\"，只有上汽能做》 腾讯新闻\n\n《江淮汽车董事长项兴初：组建了超5000人尊界专属团队，目前投入超百亿元》 新浪科技\n\n《江淮定名\"尊界\"、商标注册进入初审 华为集齐\"四界\"后渠道迭代成关键》 财联社\n\n《赛力斯拟25亿元收购问界商标专利 华为回应》 中国",
