      "title": "vol.603 历史学者“转行”农民种菜？天宽地阔，没有多少必须要做的事 feat.段志强",
      "desc": "本期主播：刘旸教主、莫莫\n本期嘉宾：段志强（复旦大学文史研究院研究员、历史学博士）\n本期我们的老嘉宾段志强老师返场，来聊聊他在崇明种菜以及古人如何种菜的有趣故事！本期包含以下内容——\n-段志强&amp;呼兰，傻傻分不清楚？\n-传出去，段志强是刘旸教主的豆包！\n-随便说一个历史话题都能聊？那聊聊神农到底种的啥吧！\n-被邻居问“你是怎么把这个红薯种这么大的”，老有成就感了！\n-段老师种菜的原则：报喜不报忧！\n-用一个词评价一下段老师的菜园：间歇性“孤儿”\n-农夫行走让一让？真正的农夫来了！\n-聊聊古时候典型的租赁制度、古代的割韭菜文学？\n-第一年种菜没种好、是做错了什么吗？段老师：全错！\n-古人奇怪的嫁接方法？\n-5年资深农民眼中：什么菜最好种？什么菜最不好种？\n-西瓜是段老师心中永远的痛？\n-段老师最喜欢吃的蔬菜和水果是什么？段老师：可不敢说！它们会难过的呀！\n-种过的新奇蔬菜：大笋瓜、金瓜？\n-种菜种的特别好的古人有哪些？\n-新型杀害虫的方法：用老灯？\n-古代占卜种地收成有什么小妙招？\n-种菜这件事治愈段老师的点？下半年想种蜜蜂？\n欢迎收听本期播客！也欢迎大家看看段志强老师的新书《我住长江尾》。2021年冬，复旦大学历史学者段志强从上海市区搬到崇明岛，教书之余，种菜读书。《我住长江尾》一书记述了作者五年来春种夏长秋收冬藏的种菜日常及与岛上乡邻的交往互动。作者将广博学识融入田园实践，赋予朴素生活以独特的人文意趣。文字轻松灵动，幽默处令人莞尔，深情处直抵人心。对于故乡、童年的追忆自然漫溢；同时，亦不乏对于现代工业文明的反思。这既是一位学者扎根土地的真实记录，也为快节奏都市生活的现代人提供了一种别样的生活样本。\n【关于我们】\n🎬收看无聊斋视频内容？关注微博、小红书、B站、抖音：@无聊斋\n🙋投稿成为无聊斋嘉宾？公众号关注「无聊斋」回复“投稿”\n👀来参与线下录制？公众号关注「无聊斋」会有不定期观众招募掉落\n👗想加入无聊斋听友群？关注 @无聊斋 小红书，加入首页听友群\n🤝商务合作？欢迎发送邮件至 luckylikeu@163.com\n✍️制作：婧文\n✂️剪辑：小天",
