      "title": "今年营销圈在发生什么？我问出了7个大咖的水下信息",
      "desc": "|本期嘉宾| \n（按出现顺序排列）\n香帅，经济学家、香帅数字经济研究中心创始人\nSteve，栗上品牌创始人\n赵仪，引响传播创始人兼CEO\n于冬琪，新能力咨询创始人、畅销书《种草》作者\nBetty Tian，万豪国际集团大中华区客户战略常务副总裁\n周宏骐，新加坡国立大学兼任教授\n董晨宇，中国人民大学新闻学院副教授\n\n|本期内容| \n8月，我作为新锐派嘉宾，连续第三年参加了小红书种草大赏。今年我获得了一个“特权”，可以跟全场所有嘉宾“私聊”。\n去之前，我觉得自己已经相当熟悉“种草”这回事了。但在跟经济学家香帅、周弘骐教授、万豪集团的Betty等一众来自行业、学界、品牌的嘉宾聊完过后，我反而一直在想：我们今天说的种草，和几年前还是一回事吗？\n让我印象很深的是，大家聊到的已经不只是“怎么把一个产品种出去”，而是一个更大的变化——品牌正在重新理解消费者，也在重新寻找那些从具体的人、具体的生活里长出来的新机会。\n所以我很想把这些对谈留下来，把我掌握的大量水下信息和干货呈现出来，和你一起重新问几个问题：\n人为什么会喜欢一个东西？\n人是怎么被看见的？\n以及，当AI越来越强的时候，我们为什么反而更需要一点“活人感”？\n\n|时间轴| \n01:43 种草是刺激和发掘欲望，然后落地成需求\n\n04:43 为“新家庭”做的洗碗机，细节都是从评论区和用户家“蹲”出来的\n\n10:54 把人当做人来看待，人买产品经常是在买想成为的自己\n\n13:24 让一部分人强烈喜欢，比让所有人均等接受，在市场上更有价值\n\n15:54 旅行从目的地驱动变成目的驱动，大家理性规划、激情预订，但到价格又理性了\n\n19:15 什么是“新要素”？超过行业共识和已知做法的东西，才可能带来新的红利\n\n22:09 洞察=洞见+体察，看到未被表达的需求，还要能翻译成业务动作\n\n25:53 营销人要学会“诉诸己”：找到答案，并让组织相信你的答案\n\n29:01 AI越强，营销人反而越要“躬身入局”：Vibe Marketing可能是一套新的底层操作系统\n\n34:09 从“甲乙方”到“自己人”：品牌、博主和用户正在建立新的共生关系\n\n38:51 从“仰视”银幕到“平视”电视到“俯视”手机，活人感和真实性是现在营销的关键词\n\n| 早鸟官宣🎉焕新·2026刀法年度品效峰会 | \n\n⏰2026年11月19-20日，杭州。2026刀法峰会早鸟票已开售，仅限200张（往年发布后10小时即售罄），欢迎下拉查看图片扫码抢位~\n\n当AI正在重新定义效率，消费者开始重新判断价值，品牌增长也进入了一个新的阶段。\n\n新的需求在哪里？品类边界还能怎么打开？老品牌如何重新激活资产？新人群如何真正破圈？从内容到交易，经营链路又该如何重塑？\n\n本届将以首次以【主论坛+三大分论坛】的形式，从“创造价值”到“传递价值”，集中讨论品牌当下最值得回答的问题。\n\n更多峰会内容及购票，戳文章了解👉 https://mp.weixin.qq.com/s/NwBhQKFxMdFEF_25HLm5Pw \n欢迎微信搜“herdao678”添加刀法小花藤或保存下方海报，微信扫码咨询👇\n\n|关于刀法智库| \n刀法 Digipont 是一家全球品牌智库，专注于新营销驱动下的品牌创新与变革。 我们以「人群战略」为核心，构建集媒体、行业会议、战略咨询与培训于一体的全球品牌营销生态。\n刀法联合并精选行业先锋，通过深度的用户研究、丰富的行业资源，以及前沿且可落地的品牌战略方法论，携手品牌创造者，共建新一代生活方式的超级品牌。\n人群时代重塑增长，做超级品牌找刀法智库，让我们一起成就中国好品牌，带领走向全世界。\n咨询、培训等业务合作，请联系zhiku@digipont.com 「刀法智库」独家人群战略方法论帮你打通战略战术战役，让生意有效率可持续，实现向超级品牌的跃迁。\n\n|关于我们| \n\n主播：刀姐doris（刀法 Digipont 创始人兼CEO）\n前互联网平台衣二三 CMO、北美支付宝市场运营负责人、纽约 MK 传播经理、北美联合利华护肤品类品牌经理。同时也是一个营销圈和消费圈的头部 KOL，全网百万粉丝。\n刀法致力于打造全球品牌的营销智库。秉承「成就中国好品牌，带领走向全世界」的核心目标，为中国品牌找到企业发展所需要的「品牌之道」、「效果之术」，以及拥有同样价值观的人才及合作伙伴，助力品牌加速。\n《温柔一刀》是一档聚焦于消费品牌、营销趋势、职业发展以及多元人生等领域的对谈性播客。由刀姐doris和刀法的小伙伴们一起制作。\n\n|本期团队| \n内容策划：栗子\n内容编辑：大稚\n内容制作：大稚\n\n|片头片尾BGM| \n开场BGM：中国雅痞\n结尾BGM：The Pussycat Dolls - out of this club",
