      "show": "高能量",
      "title": "Vol.230 产业观察43｜AI for Science 如何在制药化学合成落地？",
      "desc": "【本期课题】\nAI for science\n【栏目介绍】\n在《产业观察》这档专栏里，我们会为你厘清不同产业的历史沿革，希望能够从中找到一些底层的规律。虽然当下变化迭起，但是所有新风口都有迹可循，不同产业的发展其实也有很多相似之处。\n【免责声明】\n本节目的所有内容并非旨在提供任何形式的建议，包括但不限于投资、税收、会计或者法律上的建议。\n【本期嘉宾】\n夏宁，智化科技创始人兼CEO\n【内容索引】\n00:07 AI for Science 为什么成为一级市场里的热门方向？\n06:25 从有机化学博士到 AI 化学创业者，为什么最早选择用计算机加数据来解决化学问题？\n09:15 智化科技今天的产品和商业模式是什么？\n15:23 AI 化学里的“AI”并不只等于大模型。从机器学习、深度神经网络到 Transformer 和大模型，AI 的形态一直在变化。\n16:45 严肃科学软件不能只依赖黑盒。黑盒模型一旦出现幻觉或错误，不仅后果严重，也难以解释和改进；白盒模型的价值在于让系统可解释、可验证、可调教。\n22:58 同一套 AI 合成工具，在药物研发的不同环节有不同价值：分子设计阶段关注能不能合成，药化阶段关注能不能快速拿到分子，临床工艺放大阶段则更关心成本、风险和可量产性。\n24:55 AI 会如何影响化学研究生和初级化学工作？\n29:10 对今天进入 AI for Science 的科学家创业者来说，最重要的经验是什么？\n30:08 ChatGPT 出现后，智化科技的产品能力发生了什么变化？\n34:14 全球大型药企现在用到智能体了吗？\n37:29 今天的 AI 化学合成能力已经接近 10 年工作经验化学家的水平。\n44:49 纯 AI 背景创业者进入 AI for Science，最大的挑战是行业 know-how。不了解真实问题、数据有效性和产业需求，就很难定义问题，也很难搭建可信的白盒系统。\n47:04 AI for Science 的数据问题和通用大模型有什么不同？\n50:20 和传统软件不同，AI 每一次交互和调用都有成本；真正进入企业使用时，系统必须学会智能调度：简单问题用小模型或本地模型，关键问题再调用高级模型。\n57:56 随着中国生物医药供给端加速成长、License-out 推动研发效率竞争，中国生物医药也可能像制造业一样，在未来形成“世界医药工厂”模式。\n01:03:22 AI 化学合成的应用不只在创新药，也可以覆盖有机小分子材料，以及生物合成中的酶催化。\n01:05:38 如何看待大模型公司进入 AI for Science领域做应用？\n01:07:58 作为一家AI 化学合成公司，投资人最没有理解或者说最容易误解你们的地方是什么？\n01:12:39 AI for Science 仍处在非常早期的阶段，但趋势是必然的。就像显微镜曾经打开生物医学的新阶段，AI 也可能成为提高科学发现和研发效率的新工具，让中国在新的产业转向中获得快速发展的机会。\n【相关文章】\n文字版内容，可在峰瑞资本公众号查看。\n【本期相关】\nVol.192 宏观漫谈95｜中美关税新协定与“十五五”规划（11.5录制） \n中共中央政治局召开会议 决定召开二十届五中全会 分析研究当前经济形势和经济工作 中共中央总书记习近平主持会议-新华网 \nDMTA 循环：Design-Make-Test-Analyze，设计—合成—测试—分析\nCADD：Computer-Aided Drug Design，计算机辅助药物设计\nVol.152 宏观漫谈73｜年终特辑：“世界何以至此”决定了“我们去向何方” \n【往期链接】\nVol.158 产业观察29｜如何看待中国生物医药的“DeepSeek时刻”？ \nVol.146 产业观察25｜漫谈中国未来产业之生物制造 \nVol.127 产业观察20｜与李翔聊干细胞的前世、今生和未来 \nVol.131 产业观察21｜热议大模型是否趋冷：对话清华大学教授陈文光 \n【制作团队】\n主理人：李翔 、李丰\n制作及统筹：张英海 （13514156656）、峰小瑞（pr@freesvc.com）\n如果你喜欢我们的节目，欢迎你分享到更多的地方，也欢迎你在我们的评论区留言交流。",
