      "show": "不合时宜",
      "title": "华人家庭这个巨兽，爱与剥削为何总是同时存在",
      "desc": "【主播的话】 \n2025 年，一位以公共报道著称的华人记者，突然把笔调转向了自己的家。\n记者谭蕙芸，曾在新闻业里追问外部世界的真相，教学生如何采访弱势社群。可她自己的家中，一直藏着一个不能言说的秘密。她的哥哥，那位被寄予最高期望的长子长孙，青少年时期被情绪问题困扰。全家从香港移民到加拿大后，在\"家丑不可外扬\"的家风影响下，未能持续就医，就这样被隐去了三十年，失去机会建立成年人的独立生活和自理能力。\n她把这些经历，写成《家锁：华人家庭这个巨兽》一书。以女儿和记者的双重身份，她对这个被封存了三十年的家庭黑箱，做了一次诚实的勘探。书名里的\"家锁\"是个双关：家庭既是庇护，也是一把锁。\n我们的对话从这本书开始，聊到的却远不止一个家庭。为什么华人父母宁可把患病的孩子藏起来，也不愿让外人看见\"不完美\"？为什么\"孝\"字之下，连好好哭一场的空间都没有？移民海外真的是解药吗，还是说，个人主义的自由恰恰让一个不懂求助的人滑向了流浪的边缘？\n谭蕙芸谈到照护者如何在爱与内疚里几近崩塌，谈到\"与其买包，不如拿去做心理咨询\"这句在东亚社会仍显奢侈的话，也谈到写作本身如何成了疗愈。当她终于请人一起打开哥哥尘封的画作，一个曾被简化为\"疾病\"的人，重新成了有名字、有才华、值得尊重的个体，甚至有作品入选了 2025 年巴塞尔艺术展香港展会。\n这不只是一个家庭的创伤叙事，而是对整个东亚亲密关系底层逻辑的追问。家庭从来不只是私人的事，它是我们检验一个社会有没有公义的第一现场。\n感谢芝加哥大学克朗家族社会工作政策与实践学院对本期节目提供支持。\n\n【本期主播】 \n若含 ：小红书@若含\n王磬： 微博@王磬\n\n【本期嘉宾】 \n谭蕙芸（Vivian Tam） ：资深传媒人，香港中文大学新闻与传播学院讲师\n\n【本期剧透】 \n03:36 在外界看来模范的移民华人家庭，一直将患有精神疾病的哥哥“藏起来”\n06:57 华人家庭中“讳莫如深”的共同创伤：亲戚自杀未遂，却被家族长辈避而不谈\n11:32 最私人的即是最公共的 ，家庭内部的公义也是社会公义的基础\n18:27 华人家庭只允许“开心”一种情绪\n24:59 移民就能过得更好吗？加拿大与香港照护体系的对比 \n38:05 华人家庭的权力陷阱：爱是表演性的，爱是掌控的\n42:57 哥哥从“家丑”到艺术家的故事： 家庭问题的关键在于，有没有尊重人的个体性\n51:04 面对威权父母：放下“道歉”的执念 \n57:37 先救自己，不要等待别人给爱\n\n【相关阅读】 \n《家锁：华人家庭这个巨兽》 \n作者 ：谭蕙芸（Vivian Tam）\n出版社 ：春山出版\n出版时间 ：2025 年 6 月香港资深记者谭蕙芸以自身家庭为对象，记录患有精神疾病的哥哥、长期隐瞒病情的父母，以及整个家庭横跨三十年的照护经历。作者结合新闻调查与个人回忆，讨论华人家庭中的沉默、羞耻、控制、责任与爱，也反思移民、精神疾病污名及家庭系统如何共同塑造一个「既保护成员，也困住成员」的家庭结构。\n\n谭蕙芸哥哥创作的艺术作品（一）\n谭蕙芸哥哥的艺术作品（二）\n《要有光》 \n作者 ：梁鸿\n出版社 ：中信出版社\n出版时间 ：2025 年 7 月\n本书是非虚构代表作家梁鸿继“梁庄三部曲”之后，沉淀 5年，又一具有现实意义的非虚构作品。\n梁鸿把写作对象投向那些被困住的少年——因为情绪问题而失学、休学在家的孩子以及在退学和抑郁边缘挣扎的孩子。她用了三年时间，足迹踏遍超大城市、中等城市、县城和农村，走进家庭、学校、社会 教育机构和精神医疗机构，沉浸式采访孩子、父母、教师、医生与心理咨询师，记录他们真实的声音，试图呈现出当代中国青少年的心理图景。\n\n《静子》 \n作者： 佐野洋子\n出版社： 海峡文艺出版社\n出版时间： 2021 年 7 月\n一部感人至深的长篇散文，记录了佐野洋子与母亲迟到六十年的和解。成长过程中的种种不理解与怨恨，在得了老年痴呆症的母亲被送进养老院后，慢慢发生了变化。爱与恨、伤痛与和解交织在一起，母亲的一生被记录，不再是无人知晓的人。作为佐野洋子晚年的代表作，《静子》在日本出版后引发强烈反响，被誉为“母女和解文学中难以逾越的高峰”。\n\n柔似蜜 Rosemead \n导演 ：Eric Lin 林文德\n主演 ：Lucy Liu 刘玉玲\n上映 ：2025 年\n改编自Frank Shyong撰写的《洛杉矶时报》报道《一个垂死母亲的计划》(A Dying Mother’s Plan)。来自真实事件，被形容为“让人心碎的故事，聚焦理解心理疾病的多层面的重要性，尤其是亚裔社群中”，讲述在圣盖博谷，一个患上癌症绝症的母亲奋力想要帮助自己情绪不稳定的儿子——她发现儿子对大规模枪击案越发沉迷。\n\n我们到底做了什么？ どうすればよかったか？ \n导演 ：藤野知明（Tomoaki Fujino）\n类型 ：纪录片\n上映",
